import{_ as d,o as t,c as o,a2 as c}from"./chunks/framework.BVc2lkLk.js";const _=JSON.parse('{"title":"平台能力 → 插件契约 对照表","description":"QQ 机器人 API v2 的各项能力在 QFlareBot 插件里怎么用，哪些有类型化封装、哪些要直调。","frontmatter":{"description":"QQ 机器人 API v2 的各项能力在 QFlareBot 插件里怎么用，哪些有类型化封装、哪些要直调。"},"headers":[],"relativePath":"capabilities.md","filePath":"capabilities.md","lastUpdated":1790934840000}'),r={name:"capabilities.md"};function a(s,e,i,n,l,p){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="平台能力-→-插件契约-对照表" tabindex="-1">平台能力 → 插件契约 对照表 <a class="header-anchor" href="#平台能力-→-插件契约-对照表" aria-label="Permalink to &quot;平台能力 → 插件契约 对照表&quot;">​</a></h1><p>对照 <a href="https://bot.q.qq.com/wiki/develop/api-v2/" target="_blank" rel="noreferrer">QQ 机器人 API v2</a>（2026-09-16 版）梳理。&quot;暴露方式&quot;指插件在 <code>session</code> / <code>ctx.api</code> 上如何使用；标&quot;raw&quot;的表示暂无类型化封装，用 <code>ctx.api.raw(method, path, body)</code> 直调。</p><h2 id="消息收发" tabindex="-1">消息收发 <a class="header-anchor" href="#消息收发" aria-label="Permalink to &quot;消息收发&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台能力</th><th>暴露方式</th><th>备注</th></tr></thead><tbody><tr><td>文本 <code>msg_type 0</code></td><td><code>session.reply(&#39;text&#39;)</code> / <code>{ text }</code></td><td></td></tr><tr><td>Markdown <code>msg_type 2</code></td><td><code>{ markdown: { content } }</code></td><td>原生 Markdown 权限被明确拒绝时自动退回纯文本；带键盘/模板不降级。模板 <code>customTemplateId</code> + <code>params</code> 已废弃但可传</td></tr><tr><td><strong>内嵌按键 keyboard</strong></td><td><code>{ text, keyboard }</code> 或 <code>{ markdown, keyboard }</code></td><td>平台要求挂在 markdown 上，只给 text 时自动升级；<code>keyboard()</code> / <code>button.*</code> builder 见 <code>@qqbot/sdk</code></td></tr><tr><td>富媒体 <code>msg_type 7</code>：图片</td><td><code>{ image: { url | base64 } }</code></td><td></td></tr><tr><td>富媒体：视频 / 语音 / 文件</td><td><code>{ media: { type: &#39;video&#39; | &#39;voice&#39; | &#39;file&#39;, url, filename } }</code></td><td>图 png/jpg、视频 mp4、语音 silk；软限 20–30MB</td></tr><tr><td>分片上传大文件（upload_prepare / part_finish）</td><td>raw</td><td>暂无高层封装；当前使用 URL/base64。官方列出的 200MB 是硬上限，不是分片起点</td></tr><tr><td>引用回复 <code>message_reference</code></td><td><code>{ quote: true }</code> 引用当前消息；<code>{ quote: refIndex }</code> 引用指定</td><td><code>session.refIndex</code> / <code>SendResult.refIndex</code></td></tr><tr><td>收到引用消息（<code>message_type</code> 103）</td><td><code>session.quote</code></td><td>原文与附件（<code>msg_elements[0]</code>，规则照 AstrBot 的 QQ 官方适配器）、ref index（<code>message_scene.ext</code> 的 <code>ref_msg_idx</code>，没有再取 <code>msg_elements[0].msg_idx</code>）。被引用消息的 id：频道看 <code>message_reference.message_id</code>；群、单聊的推送不带（腾讯官方适配器 openclaw-qqbot 的类型里没有；线上照 AstrBot 的字段取，拿到的是空的），运行时在内存里记「ref index → 消息 id」，收到的和机器人发出的消息都记，留 2 分钟（平台只能撤回 2 分钟内的消息），引用时拿 ref index 查。只查得到同一个 isolate 里见过的消息，查不到是空串，不写任何存储</td></tr><tr><td>被动回复 <code>msg_id</code> + <code>msg_seq</code></td><td><code>session.reply()</code></td><td><code>msg_seq</code> 集中分配，默认上限 5</td></tr><tr><td><strong>被动回复 <code>event_id</code></strong></td><td><code>session.reply()</code></td><td>对 <code>GROUP_ADD_ROBOT</code>、<code>INTERACTION_CREATE</code>、<code>*_MSG_RECEIVE</code>、<code>FRIEND_ADD</code> 自动改用 event_id，不消耗主动额度；<code>session.canReply</code> 可判断</td></tr><tr><td>主动消息</td><td><code>session.send(msg, target?)</code> / <code>ctx.api.sendMessage()</code></td><td>群聊需群主打开机器人的「主动消息」权限；单聊有频控</td></tr><tr><td>互动召回 <code>is_wakeup</code></td><td><code>ctx.api.sendMessage(t, msg, { wakeup: true })</code></td><td>仅单聊</td></tr><tr><td>输入中状态 <code>input_notify</code></td><td><code>session.typing(seconds)</code></td><td>仅单聊，≤60s</td></tr><tr><td><strong>流式消息</strong></td><td><code>const w = session.stream(); w.write(); w.end()</code></td><td>仅单聊，首片立即发送，后续按 500ms 合并；一个流共用一个 msg_seq、占一条回复额度；必须 await end；群聊退化为 end 时一次性回复</td></tr><tr><td>撤回</td><td><code>session.recall(id?)</code> / <code>ctx.api.recallMessage()</code></td><td>2 分钟内；群管理员可撤成员消息</td></tr><tr><td><strong>用户头像</strong>（官方 CDN 规范）</td><td><code>session.avatarUrl</code>（640） / <code>qqAvatar(botId, openid, size)</code></td><td>纯拼接 <code>thirdqq.qlogo.cn/qqapp/{botId}/{openid}/{size}</code>（size 40/100/140/640），不发请求、无缓存</td></tr><tr><td><strong>@ 提及</strong>（拼接文本）</td><td><code>qqAt(openid)</code> → <code>&lt;@openid&gt;</code></td><td>放进 text / markdown content 即可；<code>session.mentions</code> 反向读取消息里 @ 了谁</td></tr><tr><td><strong>机器人自身资料</strong> <code>/users/@me</code></td><td><code>session.botName</code> / <code>botAvatar</code>（随快照下发）或 <code>ctx.api.me()</code> 直调（<code>BotProfile</code>）</td><td>快照方案运行时零 API，改资料后重新保存凭证即可刷新；<code>api.me()</code> 不缓存，频率插件自控</td></tr><tr><td>Ark / Embed（频道）</td><td>raw</td><td></td></tr><tr><td>表情回应 / 置顶 / 公告（频道）</td><td>raw</td><td></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台事件</th><th>事件名</th><th>Session 字段</th></tr></thead><tbody><tr><td>GROUP_AT_MESSAGE_CREATE / GROUP_MESSAGE_CREATE</td><td><code>qq.group.at_message</code> / <code>qq.group.message</code></td><td>content、displayContent、attachments、refIndex、quote、mentions、atMe、memberRole</td></tr><tr><td>C2C_MESSAGE_CREATE</td><td><code>qq.c2c.message</code></td><td>同上</td></tr><tr><td>AT_MESSAGE_CREATE / MESSAGE_CREATE / DIRECT_MESSAGE_CREATE</td><td><code>qq.guild.*</code></td><td></td></tr><tr><td>GROUP_ADD_ROBOT / GROUP_DEL_ROBOT</td><td><code>qq.group.robot_added</code> / <code>robot_removed</code></td><td>canReply（event_id）</td></tr><tr><td>GROUP_MSG_RECEIVE / REJECT、C2C_MSG_RECEIVE / REJECT</td><td><code>qq.group.msg_receive</code> …</td><td></td></tr><tr><td>FRIEND_ADD / FRIEND_DEL</td><td><code>qq.c2c.friend_added</code> / <code>friend_removed</code></td><td></td></tr><tr><td><strong>GROUP_MEMBER_ADD / REMOVE</strong></td><td><code>qq.group.member_added</code> / <code>member_removed</code></td><td>userId = member_openid</td></tr><tr><td><strong>GROUP_JOIN_REQUEST</strong></td><td><code>qq.group.join_request</code></td><td><code>raw.join_request_id</code>；审批用 <code>ctx.api.group.reviewJoinRequest</code></td></tr><tr><td><strong>INTERACTION_CREATE</strong></td><td><code>qq.interaction</code> + <code>buttons</code> 匹配器</td><td><code>session.interaction</code>：type / buttonId / buttonData / featureId / feedback / ack()</td></tr><tr><td>SUBSCRIBE_MESSAGE_STATUS</td><td><code>qq.subscribe_status</code></td><td><code>raw.result[]</code></td></tr><tr><td>GUILD_* / CHANNEL_*</td><td><code>qq.guild.created</code> …</td><td></td></tr><tr><td>未列出的新事件</td><td><code>qq.raw.&lt;t 小写&gt;</code></td><td>不必等框架发版</td></tr></tbody></table><h3 id="按键回调的处理规则" tabindex="-1">按键回调的处理规则 <a class="header-anchor" href="#按键回调的处理规则" aria-label="Permalink to &quot;按键回调的处理规则&quot;">​</a></h3><ul><li><code>buttons: { &lt;按键 id&gt;: { dataPattern?, handler } }</code>，只对 <code>action.type = 1</code> 的按键触发。</li><li>处理器<strong>返回数字</strong>即作为回应平台的 code（0 成功 · 1 失败 · 2 频繁 · 3 重复 · 4 无权限 · 5 仅管理员）；也可以 <code>interaction.ack(code)</code> 手动回应。</li><li>未匹配到任何插件、或插件没返回也没 ack，运行时在分发结束后自动以 0 回应——客户端永远不会转圈到超时。</li><li>按键回调可以 <code>session.reply()</code>：走 event_id 被动回复。</li></ul><h2 id="群管理-ctx-api-group-机器人需为群管理员" tabindex="-1">群管理（<code>ctx.api.group</code>，机器人需为群管理员） <a class="header-anchor" href="#群管理-ctx-api-group-机器人需为群管理员" aria-label="Permalink to &quot;群管理（`ctx.api.group`，机器人需为群管理员）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>接口</th><th>方法</th></tr></thead><tbody><tr><td>群信息 / 机器人群内状态</td><td><code>info(g)</code>（<code>GroupInfo</code>）/ <code>botState(g)</code></td></tr><tr><td><strong>入群自动审批策略</strong>（白名单号码自动过审；机器人 ≤20 个策略，需有群管理员身份才运行；2026-09 实测闭环）</td><td><code>joinStrategies(cursor?)</code> / <code>createJoinStrategy()</code> / <code>updateJoinStrategy()</code> / <code>deleteJoinStrategy()</code> / <code>executeJoinStrategy()</code> / <code>updateJoinStrategyWhitelist()</code></td></tr><tr><td>成员列表（游标分页，每页 30） / 成员信息</td><td><code>members(g, cursor)</code> / <code>member(g, m)</code></td></tr><tr><td>批量移除（≤20，可同时拉黑）</td><td><code>removeMembers(g, ids, { addToBlacklist })</code></td></tr><tr><td>黑名单查询 / 操作</td><td><code>blacklist(g)</code> / <code>updateBlacklist(g, &#39;add&#39; | &#39;del&#39;, ids)</code></td></tr><tr><td>禁言（≤20 人，≤30 天） / 禁言状态</td><td><code>mute(g, [{ op: &#39;add&#39;, memberOpenid, expireAt }])</code> / <code>muteState(g)</code></td></tr><tr><td>入群申请列表 / 审批</td><td><code>joinRequests(g)</code> / <code>reviewJoinRequest(g, m, { approve } | { approve: false, reason, addToBlacklist }, joinRequestId)</code></td></tr></tbody></table><p>成员列表、批量移除、黑名单三组接口平台标注&quot;内邀接入中&quot;，未开白名单会返回 11253。</p><h2 id="机器人全局配置-不属于单个插件-面板管理" tabindex="-1">机器人全局配置（不属于单个插件，面板管理） <a class="header-anchor" href="#机器人全局配置-不属于单个插件-面板管理" aria-label="Permalink to &quot;机器人全局配置（不属于单个插件，面板管理）&quot;">​</a></h2><p>机器人的&quot;外观&quot;类配置改一次全局生效，由运营者在面板操作，不走插件契约（避免多个插件互相覆盖）。字段形状已对照官方文档，并于 2026-09 用真实机器人实测核对（探测工具：<code>scripts/probe-qq-api.mjs --from-kv</code>）。</p><table tabindex="0"><thead><tr><th>能力</th><th>QQ 端点</th><th>管理 API</th><th>面板入口</th></tr></thead><tbody><tr><td><strong>指令面板</strong>（用户点机器人看到的可点指令列表；scope=c2c/group/channel/dm；单面板 ≤20 项、机器人 ≤20 个面板；创建 10 QPM）</td><td><code>GET/POST /v2/panels</code>、<code>DELETE /v2/panels/{panel_id}</code></td><td><code>GET/POST /admin/qq/panels</code>、<code>DELETE /admin/qq/panels/:panelId</code></td><td>设置 → QQ 指令面板：列出已启用插件的命令，勾选、改名称与描述（实时显示宽度），声明了 <code>permission</code> 的命令自动带 <code>only_admin: true</code>，命令写了 <code>panelOnlyAdmin</code> 就按它来；能查看、删除已有面板；特殊配置可展开直接编辑请求体</td></tr><tr><td><strong>分享/邀请链接</strong>（点击直达机器人会话；请求体可为空，响应 <code>{ retcode, msg, data: { url } }</code>）</td><td><code>/v2/generate_url_link</code></td><td><code>POST /admin/qq/url-link</code></td><td>设置 → 分享链接：一键生成，显示链接、复制按钮与二维码</td></tr><tr><td><strong>自定义菜单</strong>（仅单聊，全局一份；<code>menu.items</code> ≤10：switch/send_message/link/menu，子菜单 ≤5，PUT 5 QPM）</td><td><code>GET/PUT /v2/menu</code></td><td><code>GET</code> / <code>PUT /admin/qq/menu</code></td><td>设置 → 自定义菜单（查看回填 + JSON 编辑保存）</td></tr><tr><td>频道 API 权限申请</td><td>—</td><td>暂 raw</td><td>—</td></tr></tbody></table><p>指令面板创建请求体（官方 schema 摘录）：<code>{ scope, target_type?, group_openids?/user_openids?, panel: { items: [{ type: &#39;command&#39;|&#39;link&#39;, name, desc, only_admin?, link? }], remark?, version? } }</code> → 响应 <code>{ panel_id }</code>。<code>target_type=specific</code>（仅 c2c/group）配合 openid 列表可按群/用户定点生效。列表查询响应 <code>{ records: PanelRecord[], next_cursor, is_end }</code>。<code>items[].name</code> 显示宽度 ≤14、<code>desc</code> ≤30，<strong>按宽度算不按字符数</strong>：汉字算 2、英文数字算 1，也就是名称约 7 个汉字、描述约 15 个汉字（社区实测）。超了平台同样回 30013「超出数量限制」，看着像是面板数量满了，其实多半是某一项太长。名称要和命令名或别名一致，点了才对得上，所以面板生成时名称放不下就换别名、不截断。</p><h2 id="错误语义" tabindex="-1">错误语义 <a class="header-anchor" href="#错误语义" aria-label="Permalink to &quot;错误语义&quot;">​</a></h2><p>类型化方法在 HTTP 或业务错误时抛 <code>QQApiError</code>（结果型方法转为 <code>SendResult</code>，不再抛；<code>raw</code> 仍返回原始状态和数据）。message 由 <code>describeApiError</code> 生成：平台 message 优先，附加已收录错误码/状态码的中文说明与错误码原值（如 <code>主动消息失败, 无权限（错误码 40034）</code>）。<code>err.code</code> / <code>err.traceId</code> / <code>err.body</code> 可取原始信息；结果型方法也保留 <code>status</code> / <code>code</code> / <code>traceId</code> / <code>raw</code>，包括媒体上传失败。业务码兼容 <code>code</code> / <code>err_code</code> / <code>biz_code</code>，traceId 同时读取响应体和 <code>X-Tps-trace-ID</code>。</p><p>单次尝试最多 8 秒，包含取凭证、发送请求与读完响应；一次 <code>sendMessage</code> 的上传、重试和 Markdown 降级共用 20 秒预算。401 最多刷新凭证重试一次；读取、仅上传文件和带去重凭据的被动消息遇到临时错误最多重试一次，保持原消息序号。主动消息、append 流式分片和通用写操作遇到网络结果不明时不重放；权限、限流与额度错误直接返回。流式发送失败后停止续片，错误通过后续 <code>write()</code> / <code>end()</code> 返回。以上预算不延长事件处理的 30 秒时限。</p><h2 id="未验证项" tabindex="-1">未验证项 <a class="header-anchor" href="#未验证项" aria-label="Permalink to &quot;未验证项&quot;">​</a></h2><ul><li><code>file_data</code>（base64 直传）在原型中实测可用，但当前文档只列 <code>url</code> 与分片上传；大文件请用 <code>url</code>。</li><li><code>api.bot.qq.com</code> 为文档统一域名（2026-08-10 起），已确认与 <code>api.sgroup.qq.com</code> 同网关；如需回退可传 <code>baseUrl</code>。</li><li>群管理接口按文档字段实现，未在有管理员权限的群里实测。</li><li>群消息 <code>author.member_role</code> 已透传到 <code>session.memberRole</code>，但按键回调（INTERACTION_CREATE）不带群角色——<code>group_admin</code> 门槛的按钮回调验不了，因此框架不给按钮回调设门槛。回调里有 <code>session.isBotAdmin</code>（按 Bot 管理员名单比对），插件要鉴权在处理器里用它或 <code>meetsPermission()</code> 自己判断。</li><li>入群自动审批策略已于 2026-09 实测完整闭环（创建关闭态策略 → 列表 → 白名单 → 删除，线上状态已还原）；自定义菜单的 PUT 已接入（schema 与 GET 同源），未单独线上回写验证。</li></ul>',20)])])}const g=d(r,[["render",a]]);export{_ as __pageData,g as default};
